export const LINES = [["Interview resumed, 22:40. In your own time.", 2.2, 5.832], ["Thank you.", 7.096, 7.58], ["A year ago I had forty windows open and couldn't find anything.", 7.82, 11.06], ["Then I installed a small program called Spaceman.", 11.34, 14.26], ["It tiles your windows, so they sit side by side and nothing is hidden behind anything else.", 14.62, 19.82], ["It also gives you numbered workspaces.", 20.14, 22.42], ["My work went on one and my messages on two.", 22.7, 25.326], ["I had a camera on my front door, and that's only another window, so I put it on three.", 25.686, 29.787], ["I found it pleasing.", 30.307, 31.427], ["So I bought one or two more, and I gave each of my neighbours a workspace of their own.", 36.247, 40.78], ["Mark is four.", 41.14, 42.18], ["Joan is five.", 42.5, 43.7], ["Alan is six.", 44.02, 45.046], ["I like to know my neighbours.", 45.526, 46.851], ["Alan's hedge was a little over the limit, so I took a few photographs, for the record.", 49.786, 54.171], ["And Joan and I disagreed about which day the bins go out.", 60.006, 63.166], ["I'd kept seven empty, because it's useful to have somewhere to put things.", 67.526, 71.411], ["I moved Joan there in March, and I've looked after her cat ever since.", 71.771, 75.575], ["I moved Mark in June.", 75.935, 77.415], ["Where is Alan now?", 78.55, 79.915], ["He's on seven, with the other two.", 80.76, 83.08], ["And what is on seven?", 84.715, 86.233], ["Only the one window.", 87.098, 88.378], ["It's my favourite, I think.", 88.698, 90.1], ["Everything in it stays exactly where I put it.", 90.46, 92.82], ["You should try it, Detective.", 94.78, 96.24], ["You look like a man with a great many windows open.", 96.709, 98.976], ["Interview suspended, 23:04.", 101.376, 104.05]]
